-- Seed: 10 professionisti fittizi per ciascuna delle 20 regioni italiane (200 totali)
-- Generato in modo deterministico: UUID v5 stabili, P.IVA con check digit valido.
-- Rieseguibile: i record seed sono riconoscibili dal dominio PEC e vengono ripuliti prima del reinserimento.

BEGIN;

-- I profili hanno una FK verso auth.users, quindi gli account vanno creati prima.
-- Cancellarli (ON DELETE CASCADE) porta via anche profili e righe public.users.
-- Gli account non hanno password: servono solo a soddisfare il vincolo, non al login.
DELETE FROM public.professional_zones WHERE professional_id IN
  (SELECT id FROM public.professional_profiles WHERE pec LIKE '%@pec.posafacile-demo.it');
DELETE FROM public.professional_skills WHERE professional_id IN
  (SELECT id FROM public.professional_profiles WHERE pec LIKE '%@pec.posafacile-demo.it');
DELETE FROM auth.users WHERE email LIKE '%@posafacile-demo.it';

   raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
